export const files: Record<string, string> = {
  ".env.example": "# Invoice Generator needs no environment variables or API keys.\n# Everything — clients, invoices, and your business profile — is stored\n# locally in your browser (localStorage). Nothing is sent to a server.\n",
  "README.md": "# Invoice Generator\n\nCreate clients, build invoices with live-computed totals, and print a\nclean, ready-to-send PDF.\n\n## Features\n\n- A clients list (name, email, billing address) reused across invoices.\n- An invoice editor: pick a client, add line items (description,\n  quantity, unit price), and set a tax rate — subtotal, tax, and total\n  update live as you type.\n- Sequential invoice numbers, and a status (draft/sent/paid/overdue) you\n  can change right from the invoice list.\n- A print-friendly invoice preview — use your browser's Print dialog and\n  choose \"Save as PDF\".\n- A dashboard listing every invoice with client, total, status, and due\n  date, filterable by status.\n- Your business profile (name, email, address) shown on every invoice\n  header.\n\n## Getting started\n\n```bash\nnpm install\nnpm run dev\n```\n\n## Build\n\n```bash\nnpm run build\n```\n\n## Data storage\n\nClients, invoices, and your business profile are stored in your\nbrowser's `localStorage`. Nothing leaves your device, and there is no\naccount or sign-in.\n",
  "index.html": "<!doctype html>\n<html lang=\"en\">\n  <head>\n    <meta charset=\"UTF-8\" />\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n    <title>Invoice Generator</title>\n  </head>\n  <body>\n    <div id=\"root\"></div>\n    <script type=\"module\" src=\"/src/main.tsx\"></script>\n  </body>\n</html>\n",
  "package.json": "{\n  \"name\": \"invoice-generator\",\n  \"private\": true,\n  \"version\": \"1.0.0\",\n  \"type\": \"module\",\n  \"scripts\": {\n    \"dev\": \"vite\",\n    \"build\": \"vite build\",\n    \"preview\": \"vite preview\"\n  },\n  \"dependencies\": {\n    \"lucide-react\": \"^0.417.0\",\n    \"react\": \"^18.3.1\",\n    \"react-dom\": \"^18.3.1\"\n  },\n  \"devDependencies\": {\n    \"@types/react\": \"^18.3.3\",\n    \"@types/react-dom\": \"^18.3.0\",\n    \"@vitejs/plugin-react\": \"^4.3.1\",\n    \"autoprefixer\": \"^10.4.19\",\n    \"postcss\": \"^8.4.40\",\n    \"tailwindcss\": \"^3.4.7\",\n    \"typescript\": \"^5.5.4\",\n    \"vite\": \"^5.4.0\"\n  }\n}\n",
  "postcss.config.js": "export default {\n  plugins: {\n    tailwindcss: {},\n    autoprefixer: {},\n  },\n};\n",
  "src/App.tsx": "import { useEffect, useState } from \"react\";\nimport type { BusinessProfile, Client, Invoice, InvoiceStatus } from \"./types\";\nimport {\n  loadBusiness,\n  loadClients,\n  loadInvoices,\n  loadNextNumber,\n  saveBusiness,\n  saveClients,\n  saveInvoices,\n  saveNextNumber,\n} from \"./lib/storage\";\nimport { NavBar, type NavView } from \"./components/NavBar\";\nimport { Dashboard } from \"./components/Dashboard\";\nimport { ClientsPanel } from \"./components/ClientsPanel\";\nimport { BusinessSettings } from \"./components/BusinessSettings\";\nimport { InvoiceEditor } from \"./components/InvoiceEditor\";\nimport { InvoicePreview } from \"./components/InvoicePreview\";\n\ntype View =\n  | { name: \"dashboard\" }\n  | { name: \"clients\" }\n  | { name: \"business\" }\n  | { name: \"editor\" }\n  | { name: \"preview\"; invoiceId: string };\n\nfunction todayStr(): string {\n  return new Date().toISOString().slice(0, 10);\n}\n\nfunction addDaysStr(days: number): string {\n  const d = new Date();\n  d.setDate(d.getDate() + days);\n  return d.toISOString().slice(0, 10);\n}\n\nexport default function App() {\n  const [clients, setClients] = useState<Client[]>(() => loadClients());\n  const [invoices, setInvoices] = useState<Invoice[]>(() => loadInvoices());\n  const [business, setBusiness] = useState<BusinessProfile>(() => loadBusiness());\n  const [view, setView] = useState<View>({ name: \"dashboard\" });\n  const [draft, setDraft] = useState<Invoice | null>(null);\n\n  useEffect(() => saveClients(clients), [clients]);\n  useEffect(() => saveInvoices(invoices), [invoices]);\n  useEffect(() => saveBusiness(business), [business]);\n\n  function addClient(data: Omit<Client, \"id\" | \"createdAt\">) {\n    setClients((prev) => [...prev, { ...data, id: crypto.randomUUID(), createdAt: Date.now() }]);\n  }\n  function updateClient(id: string, data: Omit<Client, \"id\" | \"createdAt\">) {\n    setClients((prev) => prev.map((c) => (c.id === id ? { ...c, ...data } : c)));\n  }\n  function deleteClient(id: string) {\n    setClients((prev) => prev.filter((c) => c.id !== id));\n  }\n\n  function startNewInvoice() {\n    const n = loadNextNumber();\n    saveNextNumber(n + 1);\n    setDraft({\n      id: crypto.randomUUID(),\n      number: n,\n      clientId: clients[0]?.id ?? \"\",\n      items: [],\n      taxRate: 0,\n      status: \"draft\",\n      issueDate: todayStr(),\n      dueDate: addDaysStr(14),\n      notes: \"\",\n      createdAt: Date.now(),\n    });\n    setView({ name: \"editor\" });\n  }\n\n  function editInvoice(id: string) {\n    const existing = invoices.find((inv) => inv.id === id);\n    if (!existing) return;\n    setDraft(existing);\n    setView({ name: \"editor\" });\n  }\n\n  function saveInvoice(invoice: Invoice) {\n    setInvoices((prev) => {\n      const exists = prev.some((inv) => inv.id === invoice.id);\n      return exists ? prev.map((inv) => (inv.id === invoice.id ? invoice : inv)) : [...prev, invoice];\n    });\n    setDraft(null);\n    setView({ name: \"dashboard\" });\n  }\n\n  function cancelEdit() {\n    setDraft(null);\n    setView({ name: \"dashboard\" });\n  }\n\n  function deleteInvoice(id: string) {\n    setInvoices((prev) => prev.filter((inv) => inv.id !== id));\n  }\n\n  function changeStatus(id: string, status: InvoiceStatus) {\n    setInvoices((prev) => prev.map((inv) => (inv.id === id ? { ...inv, status } : inv)));\n  }\n\n  const navView: NavView = view.name === \"editor\" || view.name === \"preview\" ? \"dashboard\" : view.name;\n\n  return (\n    <div className=\"min-h-screen bg-gradient-to-b from-amber-50/40 via-slate-50 to-slate-50\">\n      <NavBar view={navView} onNavigate={(v) => setView({ name: v } as View)} onNewInvoice={startNewInvoice} />\n      <main className=\"mx-auto max-w-5xl px-4 py-8\">\n        {view.name === \"dashboard\" && (\n          <Dashboard\n            invoices={invoices}\n            clients={clients}\n            onEdit={editInvoice}\n            onPreview={(id) => setView({ name: \"preview\", invoiceId: id })}\n            onDelete={deleteInvoice}\n            onStatusChange={changeStatus}\n            onNewInvoice={startNewInvoice}\n          />\n        )}\n        {view.name === \"clients\" && (\n          <ClientsPanel clients={clients} onAdd={addClient} onUpdate={updateClient} onDelete={deleteClient} />\n        )}\n        {view.name === \"business\" && <BusinessSettings business={business} onSave={setBusiness} />}\n        {view.name === \"editor\" && draft && (\n          <InvoiceEditor\n            invoice={draft}\n            clients={clients}\n            onSave={saveInvoice}\n            onCancel={cancelEdit}\n            onGoToClients={() => setView({ name: \"clients\" })}\n          />\n        )}\n        {view.name === \"preview\" &&\n          (() => {\n            const inv = invoices.find((i) => i.id === view.invoiceId);\n            if (!inv) {\n              return <p className=\"text-center text-sm text-slate-500\">This invoice no longer exists.</p>;\n            }\n            return (\n              <InvoicePreview\n                invoice={inv}\n                client={clients.find((c) => c.id === inv.clientId)}\n                business={business}\n                onBack={() => setView({ name: \"dashboard\" })}\n              />\n            );\n          })()}\n      </main>\n    </div>\n  );\n}\n",
  "src/components/BusinessSettings.tsx": "import { useState } from \"react\";\nimport type { BusinessProfile } from \"../types\";\n\ninterface Props {\n  business: BusinessProfile;\n  onSave: (profile: BusinessProfile) => void;\n}\n\nexport function BusinessSettings({ business, onSave }: Props) {\n  const [form, setForm] = useState(business);\n  const [saved, setSaved] = useState(false);\n\n  function handleSubmit(e: React.FormEvent) {\n    e.preventDefault();\n    onSave({ name: form.name.trim(), email: form.email.trim(), address: form.address.trim() });\n    setSaved(true);\n    window.setTimeout(() => setSaved(false), 2000);\n  }\n\n  return (\n    <div className=\"mx-auto max-w-md\">\n      <h2 className=\"mb-1 text-lg font-semibold text-slate-900\">Your business</h2>\n      <p className=\"mb-4 text-sm text-slate-500\">Shown on the header of every invoice you create.</p>\n      <form onSubmit={handleSubmit} className=\"space-y-3\">\n        <div>\n          <label className=\"mb-1 block text-xs font-medium text-slate-600\">Business name</label>\n          <input\n            value={form.name}\n            onChange={(e) => setForm({ ...form, name: e.target.value })}\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n        </div>\n        <div>\n          <label className=\"mb-1 block text-xs font-medium text-slate-600\">Email</label>\n          <input\n            value={form.email}\n            onChange={(e) => setForm({ ...form, email: e.target.value })}\n            type=\"email\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n        </div>\n        <div>\n          <label className=\"mb-1 block text-xs font-medium text-slate-600\">Address</label>\n          <textarea\n            value={form.address}\n            onChange={(e) => setForm({ ...form, address: e.target.value })}\n            rows={3}\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n        </div>\n        <div className=\"flex items-center gap-3\">\n          <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-4 py-2 text-sm font-medium text-white hover:bg-slate-800\">\n            Save\n          </button>\n          {saved && <span className=\"text-xs text-emerald-600\">Saved</span>}\n        </div>\n      </form>\n    </div>\n  );\n}\n",
  "src/components/ClientsPanel.tsx": "import { useState } from \"react\";\nimport { Pencil, Plus, Trash2 } from \"lucide-react\";\nimport type { Client } from \"../types\";\n\ninterface Props {\n  clients: Client[];\n  onAdd: (data: Omit<Client, \"id\" | \"createdAt\">) => void;\n  onUpdate: (id: string, data: Omit<Client, \"id\" | \"createdAt\">) => void;\n  onDelete: (id: string) => void;\n}\n\ninterface FormState {\n  name: string;\n  email: string;\n  address: string;\n}\nconst EMPTY_FORM: FormState = { name: \"\", email: \"\", address: \"\" };\n\nexport function ClientsPanel({ clients, onAdd, onUpdate, onDelete }: Props) {\n  const [adding, setAdding] = useState(false);\n  const [form, setForm] = useState<FormState>(EMPTY_FORM);\n  const [editingId, setEditingId] = useState<string | null>(null);\n  const [editForm, setEditForm] = useState<FormState>(EMPTY_FORM);\n  const [confirmingId, setConfirmingId] = useState<string | null>(null);\n  const [error, setError] = useState(\"\");\n\n  function submitAdd(e: React.FormEvent) {\n    e.preventDefault();\n    if (!form.name.trim()) {\n      setError(\"Client name is required.\");\n      return;\n    }\n    onAdd({ name: form.name.trim(), email: form.email.trim(), address: form.address.trim() });\n    setForm(EMPTY_FORM);\n    setAdding(false);\n    setError(\"\");\n  }\n\n  function startEdit(c: Client) {\n    setEditingId(c.id);\n    setEditForm({ name: c.name, email: c.email, address: c.address });\n  }\n\n  function submitEdit(e: React.FormEvent) {\n    e.preventDefault();\n    if (!editingId) return;\n    if (!editForm.name.trim()) {\n      setError(\"Client name is required.\");\n      return;\n    }\n    onUpdate(editingId, { name: editForm.name.trim(), email: editForm.email.trim(), address: editForm.address.trim() });\n    setEditingId(null);\n    setError(\"\");\n  }\n\n  return (\n    <div className=\"mx-auto max-w-2xl\">\n      <div className=\"mb-4 flex items-center justify-between\">\n        <h2 className=\"text-lg font-semibold text-slate-900\">Clients</h2>\n        {!adding && (\n          <button\n            type=\"button\"\n            onClick={() => setAdding(true)}\n            className=\"flex items-center gap-1.5 rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\"\n          >\n            <Plus className=\"h-4 w-4\" /> Add client\n          </button>\n        )}\n      </div>\n\n      {error && <p className=\"mb-3 text-sm text-red-600\">{error}</p>}\n\n      {adding && (\n        <form onSubmit={submitAdd} className=\"mb-4 space-y-2 rounded-xl border border-slate-200 p-4\">\n          <input\n            autoFocus\n            value={form.name}\n            onChange={(e) => setForm({ ...form, name: e.target.value })}\n            placeholder=\"Client name\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n          <input\n            value={form.email}\n            onChange={(e) => setForm({ ...form, email: e.target.value })}\n            placeholder=\"Email\"\n            type=\"email\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n          <textarea\n            value={form.address}\n            onChange={(e) => setForm({ ...form, address: e.target.value })}\n            placeholder=\"Billing address\"\n            rows={2}\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n          <div className=\"flex justify-end gap-2\">\n            <button\n              type=\"button\"\n              onClick={() => {\n                setAdding(false);\n                setForm(EMPTY_FORM);\n                setError(\"\");\n              }}\n              className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\"\n            >\n              Cancel\n            </button>\n            <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n              Save\n            </button>\n          </div>\n        </form>\n      )}\n\n      {clients.length === 0 && !adding ? (\n        <p className=\"rounded-xl border border-dashed border-slate-300 p-8 text-center text-sm text-slate-500\">\n          No clients yet. Add one to start invoicing.\n        </p>\n      ) : (\n        <div className=\"space-y-2\">\n          {clients.map((c) => (\n            <div key={c.id} className=\"rounded-xl border border-slate-200 p-3\">\n              {editingId === c.id ? (\n                <form onSubmit={submitEdit} className=\"space-y-2\">\n                  <input\n                    autoFocus\n                    value={editForm.name}\n                    onChange={(e) => setEditForm({ ...editForm, name: e.target.value })}\n                    className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                  />\n                  <input\n                    value={editForm.email}\n                    onChange={(e) => setEditForm({ ...editForm, email: e.target.value })}\n                    type=\"email\"\n                    className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                  />\n                  <textarea\n                    value={editForm.address}\n                    onChange={(e) => setEditForm({ ...editForm, address: e.target.value })}\n                    rows={2}\n                    className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n                  />\n                  <div className=\"flex justify-end gap-2\">\n                    <button type=\"button\" onClick={() => setEditingId(null)} className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\">\n                      Cancel\n                    </button>\n                    <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-3 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n                      Save\n                    </button>\n                  </div>\n                </form>\n              ) : (\n                <div className=\"flex items-start justify-between gap-2\">\n                  <div>\n                    <p className=\"text-sm font-medium text-slate-900\">{c.name}</p>\n                    {c.email && <p className=\"text-xs text-slate-500\">{c.email}</p>}\n                    {c.address && <p className=\"whitespace-pre-line text-xs text-slate-500\">{c.address}</p>}\n                  </div>\n                  {confirmingId === c.id ? (\n                    <div className=\"flex shrink-0 items-center gap-1.5\">\n                      <button\n                        type=\"button\"\n                        onClick={() => {\n                          onDelete(c.id);\n                          setConfirmingId(null);\n                        }}\n                        className=\"text-xs font-medium text-red-600\"\n                      >\n                        Delete\n                      </button>\n                      <button type=\"button\" onClick={() => setConfirmingId(null)} className=\"text-xs text-slate-400\">\n                        Cancel\n                      </button>\n                    </div>\n                  ) : (\n                    <div className=\"flex shrink-0 items-center gap-0.5 text-slate-400\">\n                      <button type=\"button\" onClick={() => startEdit(c)} title=\"Edit\" className=\"rounded p-1.5 hover:bg-slate-100 hover:text-slate-700\">\n                        <Pencil className=\"h-3.5 w-3.5\" />\n                      </button>\n                      <button\n                        type=\"button\"\n                        onClick={() => setConfirmingId(c.id)}\n                        title=\"Delete\"\n                        className=\"rounded p-1.5 hover:bg-red-50 hover:text-red-600\"\n                      >\n                        <Trash2 className=\"h-3.5 w-3.5\" />\n                      </button>\n                    </div>\n                  )}\n                </div>\n              )}\n            </div>\n          ))}\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/Dashboard.tsx": "import { useMemo, useState } from \"react\";\nimport { Eye, FileStack, Pencil, Trash2 } from \"lucide-react\";\nimport type { Client, Invoice, InvoiceStatus } from \"../types\";\nimport { INVOICE_STATUSES } from \"../types\";\nimport { formatCurrency, formatInvoiceNumber, invoiceTotal } from \"../lib/calc\";\n\ninterface Props {\n  invoices: Invoice[];\n  clients: Client[];\n  onEdit: (id: string) => void;\n  onPreview: (id: string) => void;\n  onDelete: (id: string) => void;\n  onStatusChange: (id: string, status: InvoiceStatus) => void;\n  onNewInvoice: () => void;\n}\n\nconst STATUS_STYLES: Record<InvoiceStatus, string> = {\n  draft: \"bg-slate-100 text-slate-600\",\n  sent: \"bg-blue-100 text-blue-700\",\n  paid: \"bg-emerald-100 text-emerald-700\",\n  overdue: \"bg-red-100 text-red-700\",\n};\n\nexport function Dashboard({ invoices, clients, onEdit, onPreview, onDelete, onStatusChange, onNewInvoice }: Props) {\n  const [filter, setFilter] = useState<\"all\" | InvoiceStatus>(\"all\");\n  const [confirmingId, setConfirmingId] = useState<string | null>(null);\n\n  const clientName = (id: string) => clients.find((c) => c.id === id)?.name ?? \"Unknown client\";\n\n  const visible = useMemo(() => {\n    const list = filter === \"all\" ? invoices : invoices.filter((inv) => inv.status === filter);\n    return [...list].sort((a, b) => b.number - a.number);\n  }, [invoices, filter]);\n\n  const filters: (\"all\" | InvoiceStatus)[] = [\"all\", ...INVOICE_STATUSES];\n\n  return (\n    <div>\n      <div className=\"mb-4 flex flex-wrap gap-1.5\">\n        {filters.map((s) => (\n          <button\n            key={s}\n            type=\"button\"\n            onClick={() => setFilter(s)}\n            className={`rounded-full border px-3 py-1 text-xs font-medium capitalize transition-colors ${\n              filter === s\n                ? \"border-slate-900 bg-slate-900 text-white\"\n                : \"border-slate-200 text-slate-500 hover:border-slate-300\"\n            }`}\n          >\n            {s}\n          </button>\n        ))}\n      </div>\n\n      {visible.length === 0 ? (\n        <div className=\"flex flex-col items-center gap-3 rounded-3xl border border-dashed border-amber-200 bg-white/60 p-12 text-center text-sm text-slate-500 shadow-sm\">\n          <span className=\"flex h-12 w-12 items-center justify-center rounded-full bg-amber-100 text-amber-600\">\n            <FileStack className=\"h-5 w-5\" />\n          </span>\n          {invoices.length === 0 ? (\n            <p>\n              No invoices yet.{\" \"}\n              <button type=\"button\" onClick={onNewInvoice} className=\"font-semibold text-slate-900 underline\">\n                Create your first one\n              </button>\n              .\n            </p>\n          ) : (\n            <p>No invoices match this filter.</p>\n          )}\n        </div>\n      ) : (\n        <div className=\"overflow-x-auto rounded-2xl border border-amber-100/70 bg-white shadow-sm shadow-slate-900/[0.03]\">\n          <table className=\"w-full min-w-[640px] text-sm\">\n            <thead className=\"border-b border-slate-200 bg-slate-50 text-left text-xs uppercase text-slate-400\">\n              <tr>\n                <th className=\"px-4 py-2.5 font-medium\">Invoice</th>\n                <th className=\"px-4 py-2.5 font-medium\">Client</th>\n                <th className=\"px-4 py-2.5 font-medium\">Total</th>\n                <th className=\"px-4 py-2.5 font-medium\">Status</th>\n                <th className=\"px-4 py-2.5 font-medium\">Due</th>\n                <th className=\"px-4 py-2.5 font-medium\" />\n              </tr>\n            </thead>\n            <tbody className=\"divide-y divide-slate-100\">\n              {visible.map((inv) => (\n                <tr key={inv.id} className=\"hover:bg-slate-50/60\">\n                  <td className=\"px-4 py-2.5 font-medium text-slate-800\">{formatInvoiceNumber(inv.number)}</td>\n                  <td className=\"px-4 py-2.5 text-slate-600\">{clientName(inv.clientId)}</td>\n                  <td className=\"px-4 py-2.5 text-slate-800\">{formatCurrency(invoiceTotal(inv))}</td>\n                  <td className=\"px-4 py-2.5\">\n                    <select\n                      value={inv.status}\n                      onChange={(e) => onStatusChange(inv.id, e.target.value as InvoiceStatus)}\n                      className={`rounded-full border-0 px-2 py-1 text-xs font-medium capitalize outline-none ${STATUS_STYLES[inv.status]}`}\n                    >\n                      {INVOICE_STATUSES.map((s) => (\n                        <option key={s} value={s}>\n                          {s}\n                        </option>\n                      ))}\n                    </select>\n                  </td>\n                  <td className=\"px-4 py-2.5 text-slate-600\">{inv.dueDate}</td>\n                  <td className=\"px-4 py-2.5\">\n                    {confirmingId === inv.id ? (\n                      <div className=\"flex items-center justify-end gap-1.5\">\n                        <button\n                          type=\"button\"\n                          onClick={() => {\n                            onDelete(inv.id);\n                            setConfirmingId(null);\n                          }}\n                          className=\"text-xs font-medium text-red-600\"\n                        >\n                          Delete\n                        </button>\n                        <button type=\"button\" onClick={() => setConfirmingId(null)} className=\"text-xs text-slate-400\">\n                          Cancel\n                        </button>\n                      </div>\n                    ) : (\n                      <div className=\"flex items-center justify-end gap-1 text-slate-400\">\n                        <button\n                          type=\"button\"\n                          title=\"Preview / Print\"\n                          onClick={() => onPreview(inv.id)}\n                          className=\"rounded p-1 hover:bg-slate-100 hover:text-slate-700\"\n                        >\n                          <Eye className=\"h-3.5 w-3.5\" />\n                        </button>\n                        <button\n                          type=\"button\"\n                          title=\"Edit\"\n                          onClick={() => onEdit(inv.id)}\n                          className=\"rounded p-1 hover:bg-slate-100 hover:text-slate-700\"\n                        >\n                          <Pencil className=\"h-3.5 w-3.5\" />\n                        </button>\n                        <button\n                          type=\"button\"\n                          title=\"Delete\"\n                          onClick={() => setConfirmingId(inv.id)}\n                          className=\"rounded p-1 hover:bg-red-50 hover:text-red-600\"\n                        >\n                          <Trash2 className=\"h-3.5 w-3.5\" />\n                        </button>\n                      </div>\n                    )}\n                  </td>\n                </tr>\n              ))}\n            </tbody>\n          </table>\n        </div>\n      )}\n    </div>\n  );\n}\n",
  "src/components/InvoiceEditor.tsx": "import { useMemo, useState } from \"react\";\nimport { Plus, Trash2 } from \"lucide-react\";\nimport type { Client, Invoice, LineItem } from \"../types\";\nimport { formatCurrency, formatInvoiceNumber, subtotal, taxAmount, total } from \"../lib/calc\";\n\ninterface Props {\n  invoice: Invoice;\n  clients: Client[];\n  onSave: (invoice: Invoice) => void;\n  onCancel: () => void;\n  onGoToClients: () => void;\n}\n\nfunction newLineItem(): LineItem {\n  return { id: crypto.randomUUID(), description: \"\", quantity: 1, unitPrice: 0 };\n}\n\nexport function InvoiceEditor({ invoice, clients, onSave, onCancel, onGoToClients }: Props) {\n  const [clientId, setClientId] = useState(invoice.clientId || clients[0]?.id || \"\");\n  const [items, setItems] = useState<LineItem[]>(invoice.items.length > 0 ? invoice.items : [newLineItem()]);\n  const [taxRate, setTaxRate] = useState(invoice.taxRate);\n  const [issueDate, setIssueDate] = useState(invoice.issueDate);\n  const [dueDate, setDueDate] = useState(invoice.dueDate);\n  const [notes, setNotes] = useState(invoice.notes);\n  const [error, setError] = useState(\"\");\n\n  const sub = useMemo(() => subtotal(items), [items]);\n  const tax = useMemo(() => taxAmount(items, taxRate), [items, taxRate]);\n  const grand = useMemo(() => total(items, taxRate), [items, taxRate]);\n\n  function updateItem(id: string, patch: Partial<LineItem>) {\n    setItems((prev) => prev.map((it) => (it.id === id ? { ...it, ...patch } : it)));\n  }\n\n  function addItem() {\n    setItems((prev) => [...prev, newLineItem()]);\n  }\n\n  function removeItem(id: string) {\n    setItems((prev) => (prev.length > 1 ? prev.filter((it) => it.id !== id) : prev));\n  }\n\n  function handleSubmit(e: React.FormEvent) {\n    e.preventDefault();\n    if (!clientId) {\n      setError(\"Pick a client for this invoice.\");\n      return;\n    }\n    if (items.length === 0 || items.every((it) => !it.description.trim())) {\n      setError(\"Add at least one line item with a description.\");\n      return;\n    }\n    if (Number.isNaN(taxRate) || taxRate < 0 || taxRate > 100) {\n      setError(\"Tax rate must be between 0 and 100.\");\n      return;\n    }\n    if (!issueDate || !dueDate) {\n      setError(\"Set an issue date and due date.\");\n      return;\n    }\n    onSave({\n      ...invoice,\n      clientId,\n      items: items.filter((it) => it.description.trim()).map((it) => ({ ...it, description: it.description.trim() })),\n      taxRate,\n      issueDate,\n      dueDate,\n      notes,\n    });\n  }\n\n  if (clients.length === 0) {\n    return (\n      <div className=\"mx-auto max-w-md rounded-xl border border-dashed border-slate-300 p-8 text-center\">\n        <p className=\"text-sm text-slate-600\">Add a client before creating an invoice.</p>\n        <button\n          type=\"button\"\n          onClick={onGoToClients}\n          className=\"mt-3 rounded-lg bg-slate-900 px-4 py-2 text-sm font-medium text-white hover:bg-slate-800\"\n        >\n          Go to Clients\n        </button>\n      </div>\n    );\n  }\n\n  return (\n    <form onSubmit={handleSubmit} className=\"mx-auto max-w-3xl space-y-5\">\n      <div className=\"flex items-center justify-between\">\n        <h2 className=\"text-lg font-semibold text-slate-900\">{formatInvoiceNumber(invoice.number)}</h2>\n        <div className=\"flex gap-2\">\n          <button type=\"button\" onClick={onCancel} className=\"rounded-lg px-3 py-1.5 text-sm text-slate-600 hover:bg-slate-100\">\n            Cancel\n          </button>\n          <button type=\"submit\" className=\"rounded-lg bg-slate-900 px-4 py-1.5 text-sm font-medium text-white hover:bg-slate-800\">\n            Save invoice\n          </button>\n        </div>\n      </div>\n\n      {error && <p className=\"text-sm text-red-600\">{error}</p>}\n\n      <div className=\"grid gap-4 sm:grid-cols-3\">\n        <div>\n          <label className=\"mb-1 block text-xs font-medium text-slate-600\">Client</label>\n          <select\n            value={clientId}\n            onChange={(e) => setClientId(e.target.value)}\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          >\n            {clients.map((c) => (\n              <option key={c.id} value={c.id}>\n                {c.name}\n              </option>\n            ))}\n          </select>\n        </div>\n        <div>\n          <label className=\"mb-1 block text-xs font-medium text-slate-600\">Issue date</label>\n          <input\n            type=\"date\"\n            value={issueDate}\n            onChange={(e) => setIssueDate(e.target.value)}\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n        </div>\n        <div>\n          <label className=\"mb-1 block text-xs font-medium text-slate-600\">Due date</label>\n          <input\n            type=\"date\"\n            value={dueDate}\n            onChange={(e) => setDueDate(e.target.value)}\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n        </div>\n      </div>\n\n      <div>\n        <div className=\"mb-2 flex items-center justify-between\">\n          <label className=\"text-xs font-medium text-slate-600\">Line items</label>\n          <button type=\"button\" onClick={addItem} className=\"flex items-center gap-1 text-xs font-medium text-slate-600 hover:text-slate-900\">\n            <Plus className=\"h-3.5 w-3.5\" /> Add item\n          </button>\n        </div>\n        <div className=\"overflow-x-auto rounded-xl border border-slate-200\">\n          <table className=\"w-full min-w-[480px] text-sm\">\n            <thead className=\"bg-slate-50 text-left text-xs uppercase text-slate-400\">\n              <tr>\n                <th className=\"px-3 py-2 font-medium\">Description</th>\n                <th className=\"w-20 px-3 py-2 font-medium\">Qty</th>\n                <th className=\"w-28 px-3 py-2 font-medium\">Unit price</th>\n                <th className=\"w-28 px-3 py-2 font-medium\">Amount</th>\n                <th className=\"w-8\" />\n              </tr>\n            </thead>\n            <tbody className=\"divide-y divide-slate-100\">\n              {items.map((item) => (\n                <tr key={item.id}>\n                  <td className=\"px-3 py-1.5\">\n                    <input\n                      value={item.description}\n                      onChange={(e) => updateItem(item.id, { description: e.target.value })}\n                      placeholder=\"Description\"\n                      className=\"w-full rounded border border-transparent px-1.5 py-1 text-sm outline-none focus:border-slate-300\"\n                    />\n                  </td>\n                  <td className=\"px-3 py-1.5\">\n                    <input\n                      type=\"number\"\n                      min={0}\n                      step={1}\n                      value={item.quantity}\n                      onChange={(e) => updateItem(item.id, { quantity: Math.max(0, Number(e.target.value) || 0) })}\n                      className=\"w-full rounded border border-transparent px-1.5 py-1 text-sm outline-none focus:border-slate-300\"\n                    />\n                  </td>\n                  <td className=\"px-3 py-1.5\">\n                    <input\n                      type=\"number\"\n                      min={0}\n                      step={0.01}\n                      value={item.unitPrice}\n                      onChange={(e) => updateItem(item.id, { unitPrice: Math.max(0, Number(e.target.value) || 0) })}\n                      className=\"w-full rounded border border-transparent px-1.5 py-1 text-sm outline-none focus:border-slate-300\"\n                    />\n                  </td>\n                  <td className=\"px-3 py-1.5 text-slate-600\">{formatCurrency(item.quantity * item.unitPrice)}</td>\n                  <td className=\"px-1 py-1.5 text-right\">\n                    <button\n                      type=\"button\"\n                      onClick={() => removeItem(item.id)}\n                      disabled={items.length <= 1}\n                      className=\"rounded p-1 text-slate-400 hover:bg-red-50 hover:text-red-600 disabled:opacity-30\"\n                    >\n                      <Trash2 className=\"h-3.5 w-3.5\" />\n                    </button>\n                  </td>\n                </tr>\n              ))}\n            </tbody>\n          </table>\n        </div>\n      </div>\n\n      <div className=\"flex flex-col gap-4 sm:flex-row sm:justify-between\">\n        <div className=\"flex-1\">\n          <label className=\"mb-1 block text-xs font-medium text-slate-600\">Notes</label>\n          <textarea\n            value={notes}\n            onChange={(e) => setNotes(e.target.value)}\n            rows={3}\n            placeholder=\"Payment terms, thank-you note, etc.\"\n            className=\"w-full rounded-lg border border-slate-200 px-3 py-2 text-sm outline-none focus:border-slate-400\"\n          />\n        </div>\n        <div className=\"w-full max-w-xs space-y-1.5 rounded-xl border border-slate-200 p-4 text-sm\">\n          <div className=\"flex items-center justify-between text-slate-500\">\n            <span>Subtotal</span>\n            <span>{formatCurrency(sub)}</span>\n          </div>\n          <div className=\"flex items-center justify-between text-slate-500\">\n            <span className=\"flex items-center gap-1.5\">\n              Tax rate\n              <input\n                type=\"number\"\n                min={0}\n                max={100}\n                step={0.1}\n                value={taxRate}\n                onChange={(e) => setTaxRate(Number(e.target.value) || 0)}\n                className=\"w-14 rounded border border-slate-200 px-1 py-0.5 text-right text-xs outline-none focus:border-slate-400\"\n              />\n              %\n            </span>\n            <span>{formatCurrency(tax)}</span>\n          </div>\n          <div className=\"flex items-center justify-between border-t border-slate-200 pt-1.5 text-base font-semibold text-slate-900\">\n            <span>Total</span>\n            <span>{formatCurrency(grand)}</span>\n          </div>\n        </div>\n      </div>\n    </form>\n  );\n}\n",
  "src/components/InvoicePreview.tsx": "import { ArrowLeft, Printer } from \"lucide-react\";\nimport type { BusinessProfile, Client, Invoice } from \"../types\";\nimport { formatCurrency, formatInvoiceNumber, lineTotal, subtotal, taxAmount, total } from \"../lib/calc\";\n\ninterface Props {\n  invoice: Invoice;\n  client: Client | undefined;\n  business: BusinessProfile;\n  onBack: () => void;\n}\n\nexport function InvoicePreview({ invoice, client, business, onBack }: Props) {\n  const sub = subtotal(invoice.items);\n  const tax = taxAmount(invoice.items, invoice.taxRate);\n  const grand = total(invoice.items, invoice.taxRate);\n\n  return (\n    <div>\n      <div className=\"no-print mx-auto mb-4 flex max-w-3xl items-center justify-between\">\n        <button type=\"button\" onClick={onBack} className=\"flex items-center gap-1.5 text-sm text-slate-600 hover:text-slate-900\">\n          <ArrowLeft className=\"h-4 w-4\" /> Back\n        </button>\n        <button\n          type=\"button\"\n          onClick={() => window.print()}\n          className=\"flex items-center gap-1.5 rounded-lg bg-slate-900 px-4 py-2 text-sm font-medium text-white hover:bg-slate-800\"\n        >\n          <Printer className=\"h-4 w-4\" /> Print / Save as PDF\n        </button>\n      </div>\n\n      <div className=\"print-page mx-auto max-w-3xl rounded-xl border border-slate-200 bg-white p-10 shadow-sm\">\n        <div className=\"flex items-start justify-between border-b border-slate-200 pb-6\">\n          <div>\n            <p className=\"text-xl font-semibold text-slate-900\">{business.name || \"Your business\"}</p>\n            {business.email && <p className=\"text-sm text-slate-500\">{business.email}</p>}\n            {business.address && <p className=\"whitespace-pre-line text-sm text-slate-500\">{business.address}</p>}\n          </div>\n          <div className=\"text-right\">\n            <p className=\"text-2xl font-bold uppercase tracking-wide text-slate-800\">Invoice</p>\n            <p className=\"mt-1 text-sm text-slate-500\">{formatInvoiceNumber(invoice.number)}</p>\n          </div>\n        </div>\n\n        <div className=\"grid grid-cols-2 gap-6 py-6\">\n          <div>\n            <p className=\"text-xs font-semibold uppercase tracking-wide text-slate-400\">Billed to</p>\n            <p className=\"mt-1 text-sm font-medium text-slate-900\">{client?.name ?? \"Unknown client\"}</p>\n            {client?.email && <p className=\"text-sm text-slate-500\">{client.email}</p>}\n            {client?.address && <p className=\"whitespace-pre-line text-sm text-slate-500\">{client.address}</p>}\n          </div>\n          <div className=\"text-right\">\n            <p className=\"text-xs font-semibold uppercase tracking-wide text-slate-400\">Issue date</p>\n            <p className=\"mt-1 text-sm text-slate-700\">{invoice.issueDate}</p>\n            <p className=\"mt-3 text-xs font-semibold uppercase tracking-wide text-slate-400\">Due date</p>\n            <p className=\"mt-1 text-sm text-slate-700\">{invoice.dueDate}</p>\n          </div>\n        </div>\n\n        <table className=\"w-full text-sm\">\n          <thead className=\"border-b border-slate-200 text-left text-xs uppercase text-slate-400\">\n            <tr>\n              <th className=\"py-2 font-medium\">Description</th>\n              <th className=\"py-2 text-right font-medium\">Qty</th>\n              <th className=\"py-2 text-right font-medium\">Unit price</th>\n              <th className=\"py-2 text-right font-medium\">Amount</th>\n            </tr>\n          </thead>\n          <tbody className=\"divide-y divide-slate-100\">\n            {invoice.items.map((item) => (\n              <tr key={item.id}>\n                <td className=\"py-2 text-slate-700\">{item.description || \"—\"}</td>\n                <td className=\"py-2 text-right text-slate-600\">{item.quantity}</td>\n                <td className=\"py-2 text-right text-slate-600\">{formatCurrency(item.unitPrice)}</td>\n                <td className=\"py-2 text-right text-slate-800\">{formatCurrency(lineTotal(item))}</td>\n              </tr>\n            ))}\n          </tbody>\n        </table>\n\n        <div className=\"ml-auto mt-4 w-56 space-y-1.5 text-sm\">\n          <div className=\"flex justify-between text-slate-500\">\n            <span>Subtotal</span>\n            <span>{formatCurrency(sub)}</span>\n          </div>\n          <div className=\"flex justify-between text-slate-500\">\n            <span>Tax ({invoice.taxRate}%)</span>\n            <span>{formatCurrency(tax)}</span>\n          </div>\n          <div className=\"flex justify-between border-t border-slate-200 pt-1.5 text-base font-semibold text-slate-900\">\n            <span>Total</span>\n            <span>{formatCurrency(grand)}</span>\n          </div>\n        </div>\n\n        {invoice.notes && <div className=\"mt-8 whitespace-pre-line border-t border-slate-100 pt-4 text-sm text-slate-500\">{invoice.notes}</div>}\n      </div>\n    </div>\n  );\n}\n",
  "src/components/NavBar.tsx": "import { FileText, LayoutDashboard, Plus, Settings, Users } from \"lucide-react\";\n\nexport type NavView = \"dashboard\" | \"clients\" | \"business\";\n\ninterface Props {\n  view: NavView;\n  onNavigate: (view: NavView) => void;\n  onNewInvoice: () => void;\n}\n\nfunction navClass(active: boolean) {\n  return `flex items-center gap-1.5 rounded-full px-3 py-1.5 text-sm font-medium transition-colors ${\n    active ? \"bg-slate-900 text-white shadow-sm\" : \"text-slate-500 hover:bg-slate-100 hover:text-slate-800\"\n  }`;\n}\n\nexport function NavBar({ view, onNavigate, onNewInvoice }: Props) {\n  return (\n    <header className=\"no-print border-b border-amber-100/60 bg-white/90 backdrop-blur-sm\">\n      <div className=\"mx-auto flex max-w-5xl items-center gap-4 px-4 py-3.5\">\n        <h1 className=\"flex items-center gap-2 text-base font-bold tracking-tight text-slate-900\">\n          <span className=\"flex h-8 w-8 items-center justify-center rounded-xl bg-gradient-to-br from-slate-800 to-slate-950 text-amber-400 shadow-sm\">\n            <FileText className=\"h-4 w-4\" />\n          </span>\n          Invoices\n        </h1>\n        <nav className=\"flex items-center gap-1\">\n          <button type=\"button\" onClick={() => onNavigate(\"dashboard\")} className={navClass(view === \"dashboard\")}>\n            <LayoutDashboard className=\"h-3.5 w-3.5\" /> Dashboard\n          </button>\n          <button type=\"button\" onClick={() => onNavigate(\"clients\")} className={navClass(view === \"clients\")}>\n            <Users className=\"h-3.5 w-3.5\" /> Clients\n          </button>\n          <button type=\"button\" onClick={() => onNavigate(\"business\")} className={navClass(view === \"business\")}>\n            <Settings className=\"h-3.5 w-3.5\" /> Business\n          </button>\n        </nav>\n        <button\n          type=\"button\"\n          onClick={onNewInvoice}\n          className=\"ml-auto flex items-center gap-1.5 rounded-full bg-gradient-to-r from-amber-500 to-amber-600 px-4 py-2 text-sm font-semibold text-white shadow-sm shadow-amber-500/30 transition-all duration-150 hover:-translate-y-0.5 hover:shadow-md active:translate-y-0\"\n        >\n          <Plus className=\"h-4 w-4\" /> New invoice\n        </button>\n      </div>\n    </header>\n  );\n}\n",
  "src/index.css": "@tailwind base;\n@tailwind components;\n@tailwind utilities;\n\nhtml {\n  -webkit-font-smoothing: antialiased;\n}\n\nbody {\n  font-family: \"Inter\", system-ui, -apple-system, \"Segoe UI\", sans-serif;\n}\n\n::-webkit-scrollbar {\n  height: 8px;\n  width: 8px;\n}\n\n::-webkit-scrollbar-thumb {\n  background-color: rgba(0, 0, 0, 0.15);\n  border-radius: 9999px;\n}\n\n@media print {\n  .no-print {\n    display: none !important;\n  }\n  body {\n    background: white;\n  }\n  .print-page {\n    box-shadow: none !important;\n    margin: 0 !important;\n    padding: 0 !important;\n  }\n}\n",
  "src/lib/calc.ts": "import type { Invoice, LineItem } from \"../types\";\n\nexport function lineTotal(item: LineItem): number {\n  return item.quantity * item.unitPrice;\n}\n\nexport function subtotal(items: LineItem[]): number {\n  return items.reduce((sum, item) => sum + lineTotal(item), 0);\n}\n\nexport function taxAmount(items: LineItem[], taxRate: number): number {\n  return subtotal(items) * (taxRate / 100);\n}\n\nexport function total(items: LineItem[], taxRate: number): number {\n  return subtotal(items) + taxAmount(items, taxRate);\n}\n\nexport function invoiceTotal(invoice: Invoice): number {\n  return total(invoice.items, invoice.taxRate);\n}\n\nexport function formatCurrency(amount: number): string {\n  return amount.toLocaleString(undefined, {\n    style: \"currency\",\n    currency: \"USD\",\n    minimumFractionDigits: 2,\n    maximumFractionDigits: 2,\n  });\n}\n\nexport function formatInvoiceNumber(n: number): string {\n  return `INV-${String(n).padStart(4, \"0\")}`;\n}\n",
  "src/lib/storage.ts": "import type { BusinessProfile, Client, Invoice, InvoiceStatus } from \"../types\";\nimport { EMPTY_BUSINESS, INVOICE_STATUSES } from \"../types\";\n\nconst CLIENTS_KEY = \"invoice-generator:clients\";\nconst INVOICES_KEY = \"invoice-generator:invoices\";\nconst BUSINESS_KEY = \"invoice-generator:business\";\nconst NEXT_NUMBER_KEY = \"invoice-generator:nextNumber\";\n\nfunction isClient(value: unknown): value is Client {\n  if (!value || typeof value !== \"object\") return false;\n  const c = value as Record<string, unknown>;\n  return (\n    typeof c.id === \"string\" &&\n    typeof c.name === \"string\" &&\n    typeof c.email === \"string\" &&\n    typeof c.address === \"string\" &&\n    typeof c.createdAt === \"number\"\n  );\n}\n\nfunction isStatus(value: unknown): value is InvoiceStatus {\n  return typeof value === \"string\" && INVOICE_STATUSES.includes(value as InvoiceStatus);\n}\n\nfunction isInvoice(value: unknown): value is Invoice {\n  if (!value || typeof value !== \"object\") return false;\n  const inv = value as Record<string, unknown>;\n  return (\n    typeof inv.id === \"string\" &&\n    typeof inv.number === \"number\" &&\n    typeof inv.clientId === \"string\" &&\n    Array.isArray(inv.items) &&\n    typeof inv.taxRate === \"number\" &&\n    isStatus(inv.status) &&\n    typeof inv.issueDate === \"string\" &&\n    typeof inv.dueDate === \"string\" &&\n    typeof inv.createdAt === \"number\"\n  );\n}\n\nexport function loadClients(): Client[] {\n  try {\n    const raw = localStorage.getItem(CLIENTS_KEY);\n    if (!raw) return [];\n    const parsed = JSON.parse(raw);\n    return Array.isArray(parsed) ? parsed.filter(isClient) : [];\n  } catch {\n    return [];\n  }\n}\n\nexport function saveClients(clients: Client[]): void {\n  try {\n    localStorage.setItem(CLIENTS_KEY, JSON.stringify(clients));\n  } catch {\n    // Storage full or unavailable — in-memory state still works this session.\n  }\n}\n\nexport function loadInvoices(): Invoice[] {\n  try {\n    const raw = localStorage.getItem(INVOICES_KEY);\n    if (!raw) return [];\n    const parsed = JSON.parse(raw);\n    if (!Array.isArray(parsed)) return [];\n    return parsed.filter(isInvoice).map((inv) => ({ ...inv, notes: typeof inv.notes === \"string\" ? inv.notes : \"\" }));\n  } catch {\n    return [];\n  }\n}\n\nexport function saveInvoices(invoices: Invoice[]): void {\n  try {\n    localStorage.setItem(INVOICES_KEY, JSON.stringify(invoices));\n  } catch {\n    // Ignore — see saveClients.\n  }\n}\n\nexport function loadBusiness(): BusinessProfile {\n  try {\n    const raw = localStorage.getItem(BUSINESS_KEY);\n    if (!raw) return EMPTY_BUSINESS;\n    const parsed = JSON.parse(raw);\n    if (!parsed || typeof parsed !== \"object\") return EMPTY_BUSINESS;\n    const b = parsed as Record<string, unknown>;\n    return {\n      name: typeof b.name === \"string\" ? b.name : \"\",\n      email: typeof b.email === \"string\" ? b.email : \"\",\n      address: typeof b.address === \"string\" ? b.address : \"\",\n    };\n  } catch {\n    return EMPTY_BUSINESS;\n  }\n}\n\nexport function saveBusiness(profile: BusinessProfile): void {\n  try {\n    localStorage.setItem(BUSINESS_KEY, JSON.stringify(profile));\n  } catch {\n    // Ignore — see saveClients.\n  }\n}\n\nexport function loadNextNumber(): number {\n  try {\n    const raw = localStorage.getItem(NEXT_NUMBER_KEY);\n    const n = raw ? Number(raw) : 1;\n    return Number.isFinite(n) && n > 0 ? Math.floor(n) : 1;\n  } catch {\n    return 1;\n  }\n}\n\nexport function saveNextNumber(n: number): void {\n  try {\n    localStorage.setItem(NEXT_NUMBER_KEY, String(n));\n  } catch {\n    // Ignore — see saveClients.\n  }\n}\n",
  "src/main.tsx": "import React from \"react\";\nimport ReactDOM from \"react-dom/client\";\nimport App from \"./App\";\nimport \"./index.css\";\n\nReactDOM.createRoot(document.getElementById(\"root\")!).render(\n  <React.StrictMode>\n    <App />\n  </React.StrictMode>\n);\n",
  "src/types.ts": "export interface Client {\n  id: string;\n  name: string;\n  email: string;\n  address: string;\n  createdAt: number;\n}\n\nexport interface LineItem {\n  id: string;\n  description: string;\n  quantity: number;\n  unitPrice: number;\n}\n\nexport type InvoiceStatus = \"draft\" | \"sent\" | \"paid\" | \"overdue\";\n\nexport const INVOICE_STATUSES: InvoiceStatus[] = [\"draft\", \"sent\", \"paid\", \"overdue\"];\n\nexport interface Invoice {\n  id: string;\n  number: number;\n  clientId: string;\n  items: LineItem[];\n  taxRate: number;\n  status: InvoiceStatus;\n  issueDate: string;\n  dueDate: string;\n  notes: string;\n  createdAt: number;\n}\n\nexport interface BusinessProfile {\n  name: string;\n  email: string;\n  address: string;\n}\n\nexport const EMPTY_BUSINESS: BusinessProfile = { name: \"\", email: \"\", address: \"\" };\n",
  "tailwind.config.js": "/** @type {import('tailwindcss').Config} */\nexport default {\n  content: [\"./index.html\", \"./src/**/*.{js,ts,jsx,tsx}\"],\n  theme: {\n    extend: {},\n  },\n  plugins: [],\n};\n",
  "tsconfig.json": "{\n  \"compilerOptions\": {\n    \"target\": \"ES2020\",\n    \"useDefineForClassFields\": true,\n    \"lib\": [\"ES2020\", \"DOM\", \"DOM.Iterable\"],\n    \"module\": \"ESNext\",\n    \"skipLibCheck\": true,\n    \"moduleResolution\": \"bundler\",\n    \"allowImportingTsExtensions\": true,\n    \"resolveJsonModule\": true,\n    \"isolatedModules\": true,\n    \"noEmit\": true,\n    \"jsx\": \"react-jsx\",\n    \"strict\": true,\n    \"noUnusedLocals\": true,\n    \"noUnusedParameters\": true,\n    \"noFallthroughCasesInSwitch\": true\n  },\n  \"include\": [\"src\"],\n  \"references\": [{ \"path\": \"./tsconfig.node.json\" }]\n}\n",
  "tsconfig.node.json": "{\n  \"compilerOptions\": {\n    \"composite\": true,\n    \"skipLibCheck\": true,\n    \"module\": \"ESNext\",\n    \"moduleResolution\": \"bundler\",\n    \"allowSyntheticDefaultImports\": true,\n    \"strict\": true\n  },\n  \"include\": [\"vite.config.ts\"]\n}\n",
  "vite.config.ts": "import { defineConfig } from \"vite\";\nimport react from \"@vitejs/plugin-react\";\n\nexport default defineConfig({\n  plugins: [react()],\n});\n",
};
